import React from 'react';
import { motion } from 'framer-motion';

const Footer = () => {
  return (
    <motion.footer
      initial={{ opacity: 0, y: 20 }}
      whileInView={{ opacity: 1, y: 0 }}
      viewport={{ once: true }}
      transition={{ duration: 0.5 }}
      className="mt-20 pt-8 border-t border-slate-200 dark:border-[#233648] text-center"
    >
      <motion.p
        whileHover={{ scale: 1.02 }}
        className="text-slate-500 dark:text-[#92adc9] text-sm"
      >
        © 2023 Simon Doe. All rights reserved.
      </motion.p>
    </motion.footer>
  );
};

export default Footer;
